xpath.script:
(function() {
    var observed = false;
    function animateCounters() {
        if (observed) return;
        var counters = document.querySelectorAll('.dimsop-counter-num[data-target]');
        if (!counters.length) return;
        observed = true;
        counters.forEach(function(el) {
            var target = parseInt(el.getAttribute('data-target'), 10);
            var start = 0;
            var duration = 1800;
            var startTime = null;
            var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
            function step(ts) {
                if (!startTime) startTime = ts;
                var progress = Math.min((ts - startTime) / duration, 1);
                var eased = 1 - Math.pow(1 - progress, 3);
                var current = Math.floor(eased * target);
                el.textContent = prefix + current;
                if (progress < 1) requestAnimationFrame(step);
                else el.textContent = prefix + target;
            }
            requestAnimationFrame(step);
        });
    }
    var obs = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) animateCounters();
        });
    }, { threshold: 0.3 });
    document.addEventListener('DOMContentLoaded', function() {
        var section = document.getElementById('contadores');
        if (section) obs.observe(section);
        else setTimeout(function() {
            var s = document.getElementById('contadores');
            if (s) obs.observe(s);
        }, 500);
    });
})();

(function() {
    try {
        var t = localStorage.getItem('dimsop-theme');
        if (t === 'dark') document.documentElement.setAttribute('data-theme', 'dark');
    } catch(e) {}
})();

document.addEventListener('DOMContentLoaded', function() {
    var btn = document.getElementById('dimsop-dark-toggle');
    if (!btn) return;
    btn.addEventListener('click', function() {
        var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
        var next = isDark ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', next);
        try { localStorage.setItem('dimsop-theme', next); } catch(e) {}
        var icon = btn.querySelector('i');
        if (icon) {
            icon.className = next === 'dark' ? 'fa fa-sun-o' : 'fa fa-moon-o';
        }
    });
    // Sync icon on load
    var icon = btn.querySelector('i');
    if (icon && document.documentElement.getAttribute('data-theme') === 'dark') {
        icon.className = 'fa fa-sun-o';
    }
});
